$catalog$::jsonb) as x(sku text, product_name text, description text);
do $$
begin
  if (select count(*) from public.products p join catalog_copy_20261111 c on c.sku=p.sku) <> 11
    or (select count(distinct p.sku) from public.products p join catalog_copy_20261111 c on c.sku=p.sku) <> 11
    then raise exception 'Expected exactly one existing product for each of the 11 SKUs. No changes applied.'; end if;
end;
$$;
create table if not exists public.catalog_copy_backup_20261111 (
  product_id bigint primary key, sku text not null,
  old_title text, old_description text, new_title text not null, new_description text not null,
  saved_at timestamptz not null default now()
);
alter table public.catalog_copy_backup_20261111 enable row level security;
revoke all on public.catalog_copy_backup_20261111 from public,anon,authenticated;
grant all on public.catalog_copy_backup_20261111 to service_role;
insert into public.catalog_copy_backup_20261111(product_id,sku,old_title,old_description,new_title,new_description)
select p.id,p.sku,p.product_name,p.description,c.product_name,c.description
from public.products p join catalog_copy_20261111 c on c.sku=p.sku
on conflict(product_id) do nothing;
update public.products p
set product_name=c.product_name, description=c.description,
    admin_revision=p.admin_revision+1
from catalog_copy_20261111 c where p.sku=c.sku
  and (p.product_name is distinct from c.product_name or p.description is distinct from c.description);
-- Readback of titles and description lengths; prices and stock are shown for reference.
select p.sku,p.product_name,length(p.description) as description_characters,p.mrp,p.selling_price,p.stock
from public.products p join catalog_copy_20261111 c on c.sku=p.sku order by p.id;
commit;
